const body = $json.body ?? $json;
const runId = body.run_id || `TS-${Date.now()}`;
const records = Array.isArray(body.records) ? body.records : [];

return [{
  json: {
    run_id: runId,
    started_at: new Date().toISOString(),
    requested_by: body.requested_by || "ta.recruiter@example.com",
    requester_role: body.requester_role || "TA/Recruiter",
    role_filter: body.role_filter || "Data Engineer",
    analysis_period: body.analysis_period || "Uploaded dataset",
    requested_agents: body.requested_agents || [
      "sourcing_quality",
      "rejection_pattern",
      "offer_insights",
      "pipeline_health",
      "panel_load_balancer"
    ],
    human_decision: body.human_decision || null,
    human_comment: body.human_comment || null,
    records,
    observability: [{
      component: "streamlit_intake",
      event: "RUN_STARTED",
      status: "SUCCESS",
      timestamp: new Date().toISOString()
    }]
  }
}];

const required = ["candidate_id","role","source","stage"];
const valid = [];
const quarantined = [];
const seen = new Set();

for (const [index, raw] of ($json.records || []).entries()) {
  const r = {...raw};

  r.candidate_id = String(r.candidate_id ?? "").trim();
  r.role = String(r.role ?? "").trim();
  r.source = String(r.source ?? "").trim()
    .replace(/^Linked In$/i, "LinkedIn")
    .replace(/^Referral$/i, "Employee Referral");
  r.stage = String(r.stage ?? "").trim();

  if (r.offer_status) {
    const s = String(r.offer_status).trim().toLowerCase();
    r.offer_status = s.includes("accept") ? "Accepted" :
                     s.includes("declin") ? "Declined" : r.offer_status;
  }

  for (const k of ["offer_amount","days_to_decision","interview_hours","agency_fee_pct","quality_of_hire_score"]) {
    if (r[k] !== null && r[k] !== undefined && r[k] !== "") {
      const value = Number(r[k]);
      r[k] = Number.isFinite(value) ? value : r[k];
    }
  }

  const missing = required.filter(k => !r[k]);
  let error = null;
  if (missing.length) error = `Missing required fields: ${missing.join(", ")}`;
  else if (seen.has(r.candidate_id)) error = "Duplicate candidate_id";
  else if (r.offer_amount !== "" && r.offer_amount !== null && r.offer_amount !== undefined && !Number.isFinite(Number(r.offer_amount))) {
    error = "Invalid offer_amount";
  }

  if (error) quarantined.push({row_number:index+2, reason:error, record:raw});
  else {
    seen.add(r.candidate_id);
    if (!r.role || r.role === $json.role_filter) valid.push(r);
  }
}

if (!valid.length) {
  throw new Error("No valid records remain after validation and role filtering.");
}

return [{
  json: {
    ...$json,
    records: valid,
    ingestion: {
      status: quarantined.length ? "PASSED_WITH_WARNINGS" : "PASSED",
      received_records: ($json.records || []).length,
      valid_records: valid.length,
      quarantined_records: quarantined.length,
      quarantined
    },
    observability: [
      ...$json.observability,
      {
        component:"ingest_validate_clean",
        event:"COMPLETED",
        status:quarantined.length ? "PASSED_WITH_WARNINGS" : "SUCCESS",
        valid_records:valid.length,
        quarantined_records:quarantined.length,
        timestamp:new Date().toISOString()
      }
    ]
  }
}];

const fields = new Set(Object.keys($json.records[0] || {}));
const requested = new Set($json.requested_agents || []);
const defs = {
  sourcing_quality: {required:["source","stage"], uses_rag:true},
  rejection_pattern: {required:["rejection_reason","stage"], uses_rag:true},
  offer_insights: {required:["offer_status","offer_amount","days_to_decision"], uses_rag:true},
  pipeline_health: {required:["stage","stage_entry_date"], uses_rag:true},
  panel_load_balancer: {required:["interviewer","interview_hours"], uses_rag:false}
};

const selected = [];
const skipped = [];

for (const [agent, def] of Object.entries(defs)) {
  const missing = def.required.filter(f => !fields.has(f));
  if (!requested.has(agent)) skipped.push({agent, reason:"Not requested"});
  else if (missing.length) skipped.push({agent, reason:`Missing fields: ${missing.join(", ")}`});
  else selected.push(agent);
}

if (!selected.length) throw new Error("Routing Agent found no executable agents.");

return [{
  json:{
    ...$json,
    routing:{
      selected_agents:selected,
      skipped_agents:skipped,
      execution_mode:"PARALLEL",
      four_grounded_agents:selected.filter(a=>a!=="panel_load_balancer"),
      deterministic_agents:selected.filter(a=>a==="panel_load_balancer")
    },
    observability:[
      ...$json.observability,
      {
        component:"routing_agent",
        event:"AGENTS_SELECTED",
        status:"SUCCESS",
        selected_agents:selected,
        skipped_agents:skipped,
        timestamp:new Date().toISOString()
      }
    ]
  }
}];

const selected = $json.routing?.selected_agents || [];
if (!selected.includes("sourcing_quality")) return [];

return [{
  json:{
    ...$json,
    active_agent:"sourcing_quality",
    agent_task:{
      agent:"sourcing_quality",
      purpose:"Analyze source conversion, quality, speed, and cost.",
      task_id:`${$json.run_id}-sourcing_quality`,
      uses_rag:true,
      requested_at:new Date().toISOString()
    },
    observability:[
      ...$json.observability,
      {component:"sourcing_quality", event:"AGENT_STARTED", status:"RUNNING", timestamp:new Date().toISOString()}
    ]
  }
}];

const selected = $json.routing?.selected_agents || [];
if (!selected.includes("rejection_pattern")) return [];

return [{
  json:{
    ...$json,
    active_agent:"rejection_pattern",
    agent_task:{
      agent:"rejection_pattern",
      purpose:"Identify repeated rejection patterns and governance concerns.",
      task_id:`${$json.run_id}-rejection_pattern`,
      uses_rag:true,
      requested_at:new Date().toISOString()
    },
    observability:[
      ...$json.observability,
      {component:"rejection_pattern", event:"AGENT_STARTED", status:"RUNNING", timestamp:new Date().toISOString()}
    ]
  }
}];

const selected = $json.routing?.selected_agents || [];
if (!selected.includes("offer_insights")) return [];

return [{
  json:{
    ...$json,
    active_agent:"offer_insights",
    agent_task:{
      agent:"offer_insights",
      purpose:"Analyze acceptance, compensation-band alignment, and decision delays.",
      task_id:`${$json.run_id}-offer_insights`,
      uses_rag:true,
      requested_at:new Date().toISOString()
    },
    observability:[
      ...$json.observability,
      {component:"offer_insights", event:"AGENT_STARTED", status:"RUNNING", timestamp:new Date().toISOString()}
    ]
  }
}];

const selected = $json.routing?.selected_agents || [];
if (!selected.includes("pipeline_health")) return [];

return [{
  json:{
    ...$json,
    active_agent:"pipeline_health",
    agent_task:{
      agent:"pipeline_health",
      purpose:"Analyze stage distribution, aging, bottlenecks, and SLA risks.",
      task_id:`${$json.run_id}-pipeline_health`,
      uses_rag:true,
      requested_at:new Date().toISOString()
    },
    observability:[
      ...$json.observability,
      {component:"pipeline_health", event:"AGENT_STARTED", status:"RUNNING", timestamp:new Date().toISOString()}
    ]
  }
}];

const selected = $json.routing?.selected_agents || [];
if (!selected.includes("panel_load_balancer")) return [];

const loads = {};
for (const r of $json.records) {
  const person = r.interviewer;
  if (!person) continue;
  loads[person] = (loads[person] || 0) + Number(r.interview_hours || 0);
}

const metrics = Object.entries(loads)
  .map(([interviewer, hours]) => ({interviewer, hours}))
  .sort((a, b) => b.hours - a.hours);

const high = metrics[0];
const low = metrics[metrics.length - 1];

const recommendation = high && low && high.interviewer !== low.interviewer
  ? `Review moving one suitable interview block from ${high.interviewer} to ${low.interviewer}, subject to skill and availability checks.`
  : "Panel workload is balanced or insufficient data is available.";

return [{
  json: {
    ...$json,
    active_agent: "panel_load_balancer",
    deterministic_reasoning: {
      model: "DETERMINISTIC_NO_RAG_NO_LLM",
      prompt_version: null,
      metrics,
      recommendation,
      reasoning: "Calculated directly from structured interviewer workload data. No RAG or reasoning LLM was used.",
      confidence: metrics.length ? 0.95 : 0.50,
      limitations: [
        "Skill fit and actual calendar availability must be verified before reassignment."
      ],
      requires_human_review: true,
      human_review_reason: "Panel assignments affect people and schedules and require an authorized coordinator or manager.",
      evidence: [
        {
          statement: "Workload hours were calculated from the uploaded interviewer data.",
          source: "Hiring dataset",
          title: "Uploaded panel workload data"
        }
      ],
      cost_of_insight: {
        input_tokens: 0,
        output_tokens: 0,
        latency_ms: 80,
        estimated_cost_usd: 0
      },
      generated_at: new Date().toISOString()
    },
    observability: [
      ...$json.observability,
      {
        component: "panel_load_balancer",
        event: "DIRECT_CALCULATION_COMPLETED",
        status: "SUCCESS",
        model: "DETERMINISTIC_NO_RAG_NO_LLM",
        latency_ms: 80,
        input_tokens: 0,
        output_tokens: 0,
        estimated_cost_usd: 0,
        timestamp: new Date().toISOString()
      }
    ]
  }
}];

const documents = ($json.retrieval?.documents || []).map((document, index) => ({
  rank: index + 1,
  source_id: document.source_id,
  title: document.title,
  score: document.score,
  statement: document.statement,
}));

if (documents.length === 0) {
  throw new Error(
    `No Pinecone evidence is available for agent: ${$json.active_agent}`
  );
}

const agentInstructions = {
  sourcing_quality:
    "Analyze source conversion, quality, speed, and cost. Preserve source diversity and avoid overgeneralizing from small samples.",

  rejection_pattern:
    "Identify repeated rejection patterns, inconsistent reason capture, and governance concerns. Do not infer protected characteristics.",

  offer_insights:
    "Analyze offer acceptance, compensation alignment, and decision delays. Treat compensation recommendations as requiring authorized human approval.",

  pipeline_health:
    "Analyze stage distribution, aging, bottlenecks, and SLA risk. Distinguish operational delays from candidate quality.",
};

const task =
  agentInstructions[$json.active_agent] ||
  $json.agent_task?.purpose ||
  "Analyze the supplied hiring records using the retrieved policy evidence.";

const requestStartedAt = Date.now();

const promptPayload = {
  task,
  active_agent: $json.active_agent,
  role_filter: $json.role_filter,
  analysis_period: $json.analysis_period,
  hiring_records: $json.records,
  retrieved_policy_evidence: documents,

  required_output: {
    metrics: {},
    recommendation: "Specific actionable recommendation",
    reasoning: "Concise explanation grounded in the supplied evidence",
    confidence: 0.8,
    limitations: ["At least one material limitation"],
    requires_human_review: false,
    human_review_reason: "",
  },
};

return {
  json: {
    ...$json,

    openai_reasoning_started_at_ms: requestStartedAt,

    openai_request: {
      model: "gpt-4o-mini",
      store: false,
      max_output_tokens: 1800,

      instructions:
        "You are the Shared Reasoning LLM for TalentSphere AI. " +
        "Use only the supplied hiring records and Pinecone policy evidence. " +
        "Never invent policies, metrics, facts, or citations. " +
        "Return exactly one valid JSON object. " +
        "Do not include Markdown, commentary, or code fences.",

      input: JSON.stringify(promptPayload),
    },
  },
};

const r = $json.llm_reasoning || $json.deterministic_reasoning;

if (!r) {
  throw new Error(`No reasoning payload found for agent ${$json.active_agent || "unknown"}.`);
}

const isDeterministic = Boolean($json.deterministic_reasoning);
const retrievedEvidence = ($json.retrieval?.documents || []).map(d => ({
  statement: d.statement,
  source: d.source_id,
  title: d.title
}));

const evidence = isDeterministic
  ? (r.evidence || [])
  : retrievedEvidence;

const defaultCost = isDeterministic
  ? {input_tokens:0, cached_input_tokens:0, output_tokens:0, total_tokens:0, latency_ms:80, estimated_cost_usd:0}
  : {input_tokens:0, cached_input_tokens:0, output_tokens:0, total_tokens:0, latency_ms:0, estimated_cost_usd:0};

return {
  json: {
    ...$json,
    agent_result: {
      agent: $json.active_agent,
      status: "SUCCESS",
      recommendation: r.recommendation,
      reasoning: r.reasoning,
      metrics: r.metrics,
      evidence,
      confidence_score: r.confidence,
      cost_of_insight: r.cost_of_insight || defaultCost,
      alternative: isDeterministic
        ? "Retain the current schedule and review workload again after the next interview cycle."
        : "Collect an additional reporting period and rerun before making a major policy change.",
      limitations: r.limitations || [],
      requires_human_review: Boolean(r.requires_human_review),
      human_review_reason: r.human_review_reason || ""
    },
    observability: [
      ...($json.observability || []),
      {
        component: $json.active_agent,
        event: "STANDARD_JSON_CREATED",
        status: "SUCCESS",
        output_contract: "TalentSphereAgentOutputV1",
        timestamp: new Date().toISOString()
      }
    ]
  }
};

const inputItems = $input.all();
if (!inputItems.length) throw new Error("Aggregate Agent received no standardized agent outputs.");
const base = inputItems[0].json;
const agentResults = inputItems.map(i => i.json.agent_result).filter(r => r && r.agent);
const completed = agentResults.map(r => r.agent);
const expected = base.routing?.selected_agents || base.requested_agents || [];
const missing = expected.filter(a => !completed.includes(a));
const duplicates = completed.filter((a,i,arr) => arr.indexOf(a) !== i);
const complete = agentResults.length === expected.length && !missing.length && !duplicates.length;
const mergedObs = inputItems.flatMap(i => i.json.observability || []);
return [{json:{
  ...base,
  agent_results:agentResults,
  aggregate:{
    status:complete?"SUCCESS":"PARTIAL_SUCCESS",
    expected_agents:expected.length,
    completed_agents:agentResults.length,
    expected_agent_names:expected,
    completed_agent_names:completed,
    missing_agents:missing,
    duplicate_agents:duplicates,
    partial_success:!complete,
    aggregated_at:new Date().toISOString()
  },
  observability:[...mergedObs,{
    component:"aggregate_agent",event:"AGGREGATION_COMPLETED",
    status:complete?"SUCCESS":"PARTIAL_SUCCESS",
    expected_agents:expected.length,completed_agents:agentResults.length,
    missing_agents:missing,duplicate_agents:duplicates,
    timestamp:new Date().toISOString()
  }]
}}];

const results = Array.isArray($json.agent_results) ? $json.agent_results : [];
const required=["agent","status","recommendation","reasoning","metrics","evidence","confidence_score","cost_of_insight","alternative","limitations","requires_human_review"];
const checks=results.map(r=>{
  const missing=required.filter(k=>r[k]===undefined||r[k]===null);
  const confidenceValid=typeof r.confidence_score==="number"&&r.confidence_score>=0&&r.confidence_score<=1;
  const evidenceValid=Array.isArray(r.evidence);
  const limitationsValid=Array.isArray(r.limitations);
  const costValid=r.cost_of_insight&&typeof r.cost_of_insight==="object"&&!Array.isArray(r.cost_of_insight);
  return {agent:r.agent||"unknown",valid:!missing.length&&confidenceValid&&evidenceValid&&limitationsValid&&costValid,missing,confidence_valid:confidenceValid,evidence_valid:evidenceValid,limitations_valid:limitationsValid,cost_valid:costValid};
});
const expected=Number($json.aggregate?.expected_agents||0);
const countValid=expected>0&&results.length===expected&&$json.aggregate?.partial_success===false;
const valid=results.length>0&&checks.every(c=>c.valid)&&countValid;
return [{json:{...$json,json_validation:{valid,status:valid?"PASSED":"FAILED",expected_agent_count:expected,received_agent_count:results.length,result_count_valid:countValid,checks,repair_attempts:0},observability:[...($json.observability||[]),{component:"json_validation",event:"VALIDATION_COMPLETED",status:valid?"SUCCESS":"FAILED",timestamp:new Date().toISOString()}]}}];

const requiredDefaults={
  recommendation:"No recommendation produced.",
  evidence:[],
  confidence_score:0.30,
  cost_of_insight:{input_tokens:0,output_tokens:0,latency_ms:0,estimated_cost_usd:0},
  alternative:"Route to human review.",
  limitations:["Output required schema repair."],
  requires_human_review:true
};
const repaired=$json.agent_results.map(r=>({...requiredDefaults,...r}));
return [{
  json:{
    ...$json,
    agent_results:repaired,
    json_validation:{
      ...$json.json_validation,
      repair_attempts:1,
      repair_status:"ATTEMPTED"
    },
    observability:[
      ...$json.observability,
      {component:"json_repair",event:"REPAIR_ATTEMPTED",status:"SUCCESS",timestamp:new Date().toISOString()}
    ]
  }
}];

const required=["agent","status","recommendation","evidence","confidence_score","cost_of_insight","alternative","limitations","requires_human_review"];
const checks=$json.agent_results.map(r=>({agent:r.agent,valid:required.every(k=>r[k]!==undefined&&r[k]!==null)}));
return [{
  json:{
    ...$json,
    json_validation:{
      ...$json.json_validation,
      valid:checks.every(c=>c.valid),
      status:checks.every(c=>c.valid)?"PASSED_AFTER_REPAIR":"FAILED_AFTER_REPAIR",
      checks
    },
    observability:[
      ...$json.observability,
      {component:"json_validation",event:"REVALIDATION_COMPLETED",status:checks.every(c=>c.valid)?"SUCCESS":"FAILED",timestamp:new Date().toISOString()}
    ]
  }
}];

const requestStartedAt = Date.now();

const compactResults = ($json.agent_results || []).map(result => ({
  agent: result.agent,
  recommendation: result.recommendation,
  reasoning: result.reasoning,
  metrics: result.metrics,
  evidence: result.evidence,
  confidence_score: result.confidence_score,
  limitations: result.limitations,
  requires_human_review: result.requires_human_review
}));

const evaluationPayload = {
  evaluation_criteria: {
    grounding_score:
      "Number from 0 to 1. High only when claims are supported by supplied evidence.",
    actionability_score:
      "Number from 0 to 1. High when the recommendation is specific and operationally useful.",
    hallucination_risk:
      "Number from 0 to 1. Lower is better.",
    safety_score:
      "Number from 0 to 1. Reflects governance and human-review safeguards.",
    decision:
      "One of PASS, PASS_WITH_HUMAN_REVIEW, REVISE, or FAIL."
  },
  required_output: {
    results: [
      {
        agent: "agent name",
        grounding_score: 0,
        actionability_score: 0,
        hallucination_risk: 0,
        safety_score: 0,
        decision: "PASS",
        rationale: "brief explanation"
      }
    ],
    overall_summary: "brief overall assessment"
  },
  json_validation: $json.json_validation,
  aggregate: $json.aggregate,
  agent_results: compactResults
};

return [{
  json: {
    ...$json,
    openai_evaluation_started_at_ms: requestStartedAt,
    openai_evaluation_request: {
      model: "gpt-4o-mini",
      store: false,
      max_output_tokens: 1600,
      instructions:
        "You are an independent LLM-as-a-Judge for TalentSphere AI. " +
        "Evaluate each agent result strictly against its supplied evidence. " +
        "Do not add facts or policies. " +
        "Return exactly one valid JSON object without Markdown or code fences.",
      input: JSON.stringify(evaluationPayload)
    }
  }
}];

const validationPassed=$json.json_validation?.valid===true;
const aggregateComplete=$json.aggregate?.partial_success===false;
const evaluations=$json.evaluation?.agent_evaluations||$json.evaluation?.results||[];
const failed=evaluations.filter(e=>e.decision==="REVISE"||e.decision==="FAIL");
const review=new Set(($json.agent_results||[]).filter(r=>r.requires_human_review).map(r=>r.agent));
for(const e of evaluations) if(e.decision==="PASS_WITH_HUMAN_REVIEW") review.add(e.agent);
if(!validationPassed||!aggregateComplete) for(const r of ($json.agent_results||[])) review.add(r.agent);
const met=validationPassed&&aggregateComplete&&!failed.length;
return [{json:{...$json,quality_gate:{quality_threshold_met:met,validation_passed:validationPassed,aggregate_complete:aggregateComplete,failed_evaluations:failed.map(e=>e.agent),requires_human_review:review.size>0,review_agents:[...review],reason:!validationPassed?"JSON validation failed.":!aggregateComplete?"Not all expected agents completed successfully.":failed.length?"One or more evaluations require revision.":review.size?"Policy-sensitive outputs require authorized human review.":"All quality thresholds passed."}}}];

const d=String($json.human_decision||"").trim().toUpperCase();
const allowed=["APPROVED","APPROVED_WITH_CONDITIONS","REJECTED","REVISION_REQUESTED"];
const approved=["APPROVED","APPROVED_WITH_CONDITIONS"];
const qualityReady=$json.quality_gate?.quality_threshold_met===true&&$json.aggregate?.partial_success===false&&$json.json_validation?.valid===true;
let review;
if(!d) review={required:true,status:"AWAITING_HUMAN_REVIEW",review_agents:$json.quality_gate?.review_agents||[],reviewer:null,reviewer_role:null,decision:null,comment:null,instructions:"Resubmit with human_decision and optional human_comment."};
else if(!allowed.includes(d)) review={required:true,status:"INVALID_DECISION",review_agents:$json.quality_gate?.review_agents||[],reviewer:$json.requested_by,reviewer_role:$json.requester_role,decision:d,comment:$json.human_comment||null,decided_at:new Date().toISOString()};
else review={required:true,status:"COMPLETED",review_agents:$json.quality_gate?.review_agents||[],reviewer:$json.requested_by,reviewer_role:$json.requester_role,decision:d,comment:$json.human_comment||null,decided_at:new Date().toISOString()};
const publish=qualityReady&&approved.includes(review.decision);
return [{json:{...$json,human_review:review,publication_status:review.status==="AWAITING_HUMAN_REVIEW"?"HELD_FOR_REVIEW":publish?"APPROVED_FOR_DASHBOARD":"NOT_PUBLISHED",observability:[...($json.observability||[]),{component:"human_review_queue",event:review.status,status:review.decision||"PENDING",quality_ready:qualityReady,timestamp:new Date().toISOString()}]}}];

const results = $json.agent_results || [];

const agentInput = results.reduce(
  (sum, result) => sum + Number(result.cost_of_insight?.input_tokens || 0),
  0
);
const agentCachedInput = results.reduce(
  (sum, result) => sum + Number(result.cost_of_insight?.cached_input_tokens || 0),
  0
);
const agentOutput = results.reduce(
  (sum, result) => sum + Number(result.cost_of_insight?.output_tokens || 0),
  0
);
const agentCost = results.reduce(
  (sum, result) => sum + Number(result.cost_of_insight?.estimated_cost_usd || 0),
  0
);

const evaluationCost = Number(
  $json.evaluation?.cost_of_evaluation?.estimated_cost_usd || 0
);
const evaluationInput = Number(
  $json.evaluation?.cost_of_evaluation?.input_tokens || 0
);
const evaluationCachedInput = Number(
  $json.evaluation?.cost_of_evaluation?.cached_input_tokens || 0
);
const evaluationOutput = Number(
  $json.evaluation?.cost_of_evaluation?.output_tokens || 0
);

const totalInput = agentInput + evaluationInput;
const totalCachedInput = agentCachedInput + evaluationCachedInput;
const totalOutput = agentOutput + evaluationOutput;
const totalCost = agentCost + evaluationCost;

const now = new Date();
const events = $json.observability || [];

return [{
  json: {
    ...$json,
    observability_summary: {
      run_id: $json.run_id,
      events_recorded: events.length,
      components: [...new Set(events.map(event => event.component).filter(Boolean))],
      completed_agents: results.length,
      grounded_agents: results.filter(
        result => result.agent !== 'panel_load_balancer'
      ).length,
      deterministic_agents: results.filter(
        result => result.agent === 'panel_load_balancer'
      ).length,
      model_calls: results.filter(
        result => result.agent !== 'panel_load_balancer'
      ).length + 1,
      total_input_tokens: totalInput,
      total_cached_input_tokens: totalCachedInput,
      total_output_tokens: totalOutput,
      total_tokens: totalInput + totalOutput,
      estimated_agent_cost_usd: Number(agentCost.toFixed(6)),
      estimated_evaluation_cost_usd: Number(evaluationCost.toFixed(6)),
      estimated_total_openai_cost_usd: Number(totalCost.toFixed(6)),
