const recs=[
  "Cache role-specific policy retrieval such as compensation bands and SLAs.",
  "Keep deterministic metric calculations outside the LLM.",
  "Execute independent insight agents in parallel.",
  "Use a lower-cost reasoning model for low-risk agents and a stronger model for Offer Insights.",
  "Compress retrieved context when token usage exceeds the configured threshold."
];
return [{json:{...$json,optimization:{applies_to:"FUTURE_RUNS",recommendations:recs}}}];

const results=Array.isArray($json.agent_results)?$json.agent_results:[];
const completed=$json.aggregate?.completed_agent_names||results.map(r=>r.agent);
const selected=$json.routing?.selected_agents||$json.requested_agents||[];
const quality=$json.quality_gate?.quality_threshold_met===true;
const complete=$json.aggregate?.partial_success===false;
const valid=$json.json_validation?.valid===true;
const decision=$json.human_review?.decision||$json.human_decision||null;
const approved=["APPROVED","APPROVED_WITH_CONDITIONS","AUTO_PUBLISH"];
const review=$json.quality_gate?.requires_human_review===true;
const publish=quality&&complete&&valid&&(!review||approved.includes(decision))&&$json.publication_status==="APPROVED_FOR_DASHBOARD";
let status,message;
if(!quality||!complete||!valid){status="FAILED_QUALITY_GATE";message="Analysis completed but did not meet the publication quality threshold.";}
else if(review&&!approved.includes(decision)){status="AWAITING_HUMAN_REVIEW";message="Analysis completed and is awaiting authorized human review.";}
else if(publish){status="COMPLETED";message="Analysis completed and is ready for the Streamlit dashboard.";}
else{status="COMPLETED_NOT_PUBLISHED";message="Analysis completed but was not approved for publication.";}
return [{json:{success:quality&&complete&&valid,run_id:$json.run_id,status,message,streamlit_dashboard:{publish,run_summary:{requested_by:$json.requested_by,requester_role:$json.requester_role,role_filter:$json.role_filter,analysis_period:$json.analysis_period,valid_records:$json.ingestion?.valid_records??0,quarantined_records:$json.ingestion?.quarantined_records??0,selected_agents:selected,completed_agents:completed,missing_agents:$json.aggregate?.missing_agents||[],duplicate_agents:$json.aggregate?.duplicate_agents||[],partial_success:$json.aggregate?.partial_success??true},insights:results,evaluation:$json.evaluation||{},json_validation:$json.json_validation||{},quality_gate:$json.quality_gate||{},human_review:$json.human_review||{},observability:$json.observability_summary||{},optimization:$json.optimization||{}}}}];

const agent = $json.active_agent;

if (!agent) {
  throw new Error("Prepare Pinecone Query did not receive active_agent.");
}

const queryByAgent = {
  sourcing_quality: [
    "Retrieve approved recruiting source quality benchmarks, agency usage rules, source diversity safeguards, hire conversion guidance, quality-of-hire guidance, cost guidance, and decision-speed policies.",
