  ].join(" ")
};

const queryText = queryByAgent[agent] ||
  `Retrieve approved TalentSphere policies, benchmarks, and service-level guidance for ${agent}.`;

return {
  json: {
    ...$json,
    rag_query: {
      agent,
      text: queryText,
