const source = $('6A. Prepare Pinecone Retrieval Query').item.json;
const response = $json || {};

if (response.error) {
  throw new Error(`Pinecone retrieval failed for ${source.active_agent}: ${response.error.message || JSON.stringify(response.error)}`);
}

const hits = response.result?.hits || response.hits || [];
const documents = hits.map((hit, index) => {
  const fields = hit.fields || hit.metadata || {};
  return {
    source_id: fields.document_id || hit._id || hit.id || `pinecone-hit-${index + 1}`,
    title: fields.filename || fields.document_id || hit._id || `Retrieved policy ${index + 1}`,
