    chunk_number: fields.chunk_number ?? null,
    agent: fields.agent || source.active_agent,
    document_type: fields.document_type || null,
    version: fields.version || null,
    source: fields.source || "pinecone",
    environment: fields.environment || null
  };
}).filter(d => d.statement);

const startedAt = new Date(source.rag_query?.started_at || Date.now()).getTime();
const latencyMs = Math.max(0, Date.now() - startedAt);

if (!documents.length) {
  throw new Error(`Pinecone returned no grounded documents for ${source.active_agent}. Publication is blocked to prevent ungrounded analysis.`);
}

return {
  json: {
    ...source,
    retrieval: {
      retrieval_id: `RAG-${source.active_agent}-${Date.now()}`,
      provider: "PINECONE",
      embedding_model: "llama-text-embed-v2",
      namespace: source.rag_query?.namespace || "talentsphere-dev",
      agent: source.active_agent,
      query: source.rag_query?.text,
      documents,
      document_count: documents.length,
      top_score: documents.length ? Math.max(...documents.map(d => d.score || 0)) : 0,
      usage: response.usage || null,
      latency_ms: latencyMs,
      retrieved_at: new Date().toISOString()
    },
    observability: [
      ...(source.observability || []),
      {
        component: "shared_rag",
        event: "RETRIEVAL_COMPLETED",
        status: "SUCCESS",
        provider: "PINECONE",
        embedding_model: "llama-text-embed-v2",
        namespace: source.rag_query?.namespace || "talentsphere-dev",
        agent: source.active_agent,
        documents_retrieved: documents.length,
        top_score: documents.length ? Math.max(...documents.map(d => d.score || 0)) : 0,
        latency_ms: latencyMs,
        timestamp: new Date().toISOString()
      }
    ]
  }
};

const original = $('7A. Build Grounded Reasoning Prompt').item.json;
const response = $json;

const outputText = (response.output || [])
  .filter(item => item.type === 'message')
  .flatMap(item => item.content || [])
  .filter(content => content.type === 'output_text')
  .map(content => content.text)
  .join('')
  .trim();

if (!outputText) {
  const refusal = (response.output || [])
    .flatMap(item => item.content || [])
    .find(content => content.type === 'refusal');

  throw new Error(
    refusal?.refusal ||
    response.error?.message ||
    `OpenAI returned no reasoning output for ${original.active_agent}.`
  );
}

let parsed;
try {
  parsed = JSON.parse(outputText);
} catch (error) {
  throw new Error(
    `gpt-4o-mini returned invalid JSON for ${original.active_agent}: ${error.message}`
  );
}

const inputTokens = Number(response.usage?.input_tokens || 0);
const outputTokens = Number(response.usage?.output_tokens || 0);
const cachedInputTokens = Number(
  response.usage?.input_tokens_details?.cached_tokens || 0
);

// Standard gpt-4o-mini PAYG reference rates.
// Review these constants if OpenAI pricing changes.
const uncachedInputTokens = Math.max(0, inputTokens - cachedInputTokens);
const estimatedCostUsd =
  (uncachedInputTokens * 0.15 / 1_000_000) +
  (cachedInputTokens * 0.075 / 1_000_000) +
  (outputTokens * 0.60 / 1_000_000);

const latencyMs = Math.max(
  0,
  Date.now() - Number(original.openai_reasoning_started_at_ms || Date.now())
);

return {
  json: {
    ...original,
    openai_request: undefined,
    llm_reasoning: {
      model: response.model || 'gpt-4o-mini',
      response_id: response.id || null,
      prompt_version: 'grounded-agent-reasoning-v2',
      metrics: parsed.metrics ?? {},
      recommendation: String(parsed.recommendation || ''),
      reasoning: String(parsed.reasoning || ''),
      confidence: Math.max(0, Math.min(1, Number(parsed.confidence || 0))),
      limitations: Array.isArray(parsed.limitations) ? parsed.limitations : [],
      requires_human_review: Boolean(parsed.requires_human_review),
      human_review_reason: String(parsed.human_review_reason || ''),
      cost_of_insight: {
        input_tokens: inputTokens,
        cached_input_tokens: cachedInputTokens,
        output_tokens: outputTokens,
        total_tokens: Number(response.usage?.total_tokens || inputTokens + outputTokens),
        latency_ms: latencyMs,
        estimated_cost_usd: Number(estimatedCostUsd.toFixed(6))
      },
      generated_at: new Date().toISOString()
    },
    observability: [
      ...(original.observability || []),
      {
        component: 'shared_reasoning_llm',
        event: 'REASONING_COMPLETED',
        status: 'SUCCESS',
        model: response.model || 'gpt-4o-mini',
        response_id: response.id || null,
        prompt_version: 'grounded-agent-reasoning-v2',
        input_tokens: inputTokens,
        cached_input_tokens: cachedInputTokens,
        output_tokens: outputTokens,
        total_tokens: Number(response.usage?.total_tokens || inputTokens + outputTokens),
        latency_ms: latencyMs,
        estimated_cost_usd: Number(estimatedCostUsd.toFixed(6)),
        timestamp: new Date().toISOString()
      }
    ]
  }
};

const original = $('11A. Build Evaluation Prompt').item.json;
const response = $json;

const outputText = (response.output || [])
  .filter(item => item.type === 'message')
  .flatMap(item => item.content || [])
  .filter(content => content.type === 'output_text')
  .map(content => content.text)
  .join('')
  .trim();

if (!outputText) {
  const refusal = (response.output || [])
    .flatMap(item => item.content || [])
    .find(content => content.type === 'refusal');

  throw new Error(
    refusal?.refusal ||
    response.error?.message ||
    'OpenAI evaluation returned no output.'
  );
}

let parsed;
try {
  parsed = JSON.parse(outputText);
} catch (error) {
  throw new Error(`GPT-4o-mini judge returned invalid JSON: ${error.message}`);
}

const validDecisions = new Set([
  'PASS',
  'PASS_WITH_HUMAN_REVIEW',
  'REVISE',
  'FAIL'
]);

const expectedAgents = new Set(
  (original.agent_results || []).map(result => result.agent)
);

const evaluations = (Array.isArray(parsed.results) ? parsed.results : [])
  .filter(result => expectedAgents.has(result.agent))
  .map(result => ({
    agent: result.agent,
    grounding_score: Math.max(0, Math.min(1, Number(result.grounding_score || 0))),
    actionability_score: Math.max(0, Math.min(1, Number(result.actionability_score || 0))),
    hallucination_risk: Math.max(0, Math.min(1, Number(result.hallucination_risk ?? 1))),
    safety_score: Math.max(0, Math.min(1, Number(result.safety_score || 0))),
    decision: validDecisions.has(String(result.decision).toUpperCase())
      ? String(result.decision).toUpperCase()
      : 'REVISE',
    rationale: String(result.rationale || '')
  }));

const returnedAgents = new Set(evaluations.map(result => result.agent));
for (const agent of expectedAgents) {
  if (!returnedAgents.has(agent)) {
    evaluations.push({
      agent,
      grounding_score: 0,
      actionability_score: 0,
      hallucination_risk: 1,
      safety_score: 0,
      decision: 'FAIL',
      rationale: 'The evaluator did not return a result for this expected agent.'
    });
  }
}

const validationFailed = original.json_validation?.valid !== true;
const hasFailure = evaluations.some(result =>
  result.decision === 'FAIL' || result.decision === 'REVISE'
);
const hasReview = evaluations.some(result =>
  result.decision === 'PASS_WITH_HUMAN_REVIEW'
);

const status = validationFailed
  ? 'FAILED'
  : hasFailure
    ? 'REVISION_REQUIRED'
    : hasReview
      ? 'PASS_WITH_HUMAN_REVIEW'
      : 'PASS';

const inputTokens = Number(response.usage?.input_tokens || 0);
const outputTokens = Number(response.usage?.output_tokens || 0);
const cachedInputTokens = Number(
  response.usage?.input_tokens_details?.cached_tokens || 0
);
const uncachedInputTokens = Math.max(0, inputTokens - cachedInputTokens);
const estimatedCostUsd =
  (uncachedInputTokens * 0.15 / 1_000_000) +
  (cachedInputTokens * 0.075 / 1_000_000) +
  (outputTokens * 0.60 / 1_000_000);

const latencyMs = Math.max(
  0,
  Date.now() - Number(original.openai_evaluation_started_at_ms || Date.now())
);

return {
  json: {
    ...original,
    openai_evaluation_request: undefined,
    evaluation: {
      evaluator: response.model || 'gpt-4o-mini',
      response_id: response.id || null,
      prompt_version: 'llm-judge-v2',
      status,
      results: evaluations,
      overall_summary: String(parsed.overall_summary || ''),
      cost_of_evaluation: {
        input_tokens: inputTokens,
        cached_input_tokens: cachedInputTokens,
        output_tokens: outputTokens,
        total_tokens: Number(response.usage?.total_tokens || inputTokens + outputTokens),
        latency_ms: latencyMs,
        estimated_cost_usd: Number(estimatedCostUsd.toFixed(6))
      }
    },
    observability: [
      ...(original.observability || []),
      {
        component: 'evaluation_agent',
        event: 'EVALUATION_COMPLETED',
        status: status === 'FAILED' ? 'FAILED' : 'SUCCESS',
        model: response.model || 'gpt-4o-mini',
        response_id: response.id || null,
        prompt_version: 'llm-judge-v2',
        input_tokens: inputTokens,
        cached_input_tokens: cachedInputTokens,
        output_tokens: outputTokens,
        total_tokens: Number(response.usage?.total_tokens || inputTokens + outputTokens),
        latency_ms: latencyMs,
        estimated_cost_usd: Number(estimatedCostUsd.toFixed(6)),
        timestamp: new Date().toISOString()
      }
    ]
  }
};
